corrected_code:
class DeleteDeveloperWebhook(graphene.Mutation):
    class Arguments:
        webhook_id = graphene.Int(required=True)

    deleted_id = graphene.Int()

    def mutate(self, info, webhook_id):
        user = info.context.user
        if not user.is_authenticated:
            raise GraphQLError("Authentication required.")
        try:
            hook = DeveloperWebhook.objects.get(id=webhook_id, developer=user)
        except DeveloperWebhook.DoesNotExist:
            raise GraphQLError("Webhook not found or access denied.")
        hook.delete()
        return DeleteDeveloperWebhook(deleted_id=webhook_id)
